import json
from pathlib import Path
obj=lambda props,required:dict(type='object',properties=props,required=required,additionalProperties=False)
ref=lambda name:{'$ref':'#/$defs/'+name}
ident={'type':'string','pattern':'^[A-Za-z][A-Za-z0-9_-]{0,63}$'}
string={'type':'string','maxLength':1000}
number={'type':['number','null'],'minimum':-1e15,'maximum':1e15}
array=lambda item,n=10000:dict(type='array',items=item,maxItems=n)
column=obj({'key':ident,'label':string,'type':{'enum':['text','number','date','status']},'unit':{'type':'string','maxLength':30},'format':{'enum':['text','number','currency','percent','date','time','status']}},['key','label','type'])
row=obj({'id':ident,'values':{'type':'object','additionalProperties':{'type':['string','number','null']}},'sources':array(ident,100),'cellSources':{'type':'object','additionalProperties':array(ident,100)}},['id','values'])
source=obj({'id':ident,'url':{'type':'string','pattern':'^https://','maxLength':2000},'title':string,'retrievedAt':{'type':'string','format':'date-time'}},['id','url','title'])
sort=obj({'field':ident,'direction':{'enum':['asc','desc']}},['field','direction'])
flt=obj({'field':ident,'op':{'enum':['eq','ne','contains','gt','gte','lt','lte','between','missing','present']},'value':{'type':['string','number']},'end':{'type':['string','number']}},['field','op'])
chart=obj({'chartType':{'enum':['bar','horizontalBar','line','area','scatter','pie','donut','histogram','heatmap','candlestick','combo']},'x':ident,'y':ident,'value':ident,'bins':{'type':'integer','minimum':2,'maximum':50},'series':array(obj({'field':ident,'label':string,'chartType':{'enum':['bar','line']}},['field']),6),'title':string,**{k:ident for k in ['open','close','high','low']}},['chartType'])
view=obj({'schemaVersion':{'const':'1.1'},'type':{'const':'dataView'},'id':ident,'revision':{'type':'integer','minimum':0},'title':string,'summary':{'type':'string','maxLength':4000},'provenance':{'enum':['user','retrieved','unverified','example','calculated']},'dataset':obj({'id':ident,'columns':array(ref('column'),32),'rows':array(ref('row'))},['id','columns','rows']),'charts':array(ref('chart'),12),'sources':array(ref('source'),100),'view':obj({'search':string,'filters':array(ref('filter'),32),'sorts':array(ref('sort'),32),'columns':array(ident,32)},[])},['schemaVersion','type','id','revision','title','provenance','dataset'])
ops=[]
def operation(name,props,required):ops.append(obj({'op':{'const':name},**props},['op']+required))
operation('sort',{'sorts':array(ref('sort'),32)},['sorts']);operation('filter',{'filters':array(ref('filter'),32)},['filters']);operation('search',{'text':string},['text']);operation('removeRows',{'ids':array(ident)},['ids']);operation('dropColumn',{'field':ident},['field']);operation('addRows',{'rows':array(ref('row'))},['rows']);operation('addSources',{'sources':array(ref('source'),100)},['sources']);operation('addColumn',{'column':ref('column'),'values':{'type':'object','additionalProperties':{'type':['string','number','null']}},'sources':{'type':'object','additionalProperties':array(ident,100)}},['column','values']);operation('chart',{'chart':ref('chart')},['chart']);operation('aggregate',{'field':ident,'kind':{'enum':['sum','mean','average','min','max','median','count','percentageChange','trend']}},['field','kind']);operation('group',{'by':ident,'field':ident,'kind':{'enum':['sum','mean','average','min','max','median','count']}},['by','field','kind']);operation('calculate',{'column':ref('column'),'kind':{'enum':['percentage','percentageChange','difference','ratio','rank']},'field':ident,'other':ident,'direction':{'enum':['asc','desc']},'denominator':{'oneOf':[{'type':'number'},obj({'aggregate':{'enum':['sum','mean','median','min','max','count']},'field':ident},['aggregate','field'])]}},['column','kind','field'])
operation('convert',{'field':ident,'column':ref('column'),'rate':obj({'from':string,'to':string,'value':{'type':'number'},'source':ident},['from','to'])},['field','column','rate'])
patch=obj({'schemaVersion':{'const':'1.1'},'type':{'const':'dataUpdate'},'target':ident,'baseRevision':{'type':'integer','minimum':0},'operations':array({'oneOf':ops},20)},['schemaVersion','type','target','baseRevision','operations'])
schema={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'https://yoeai.online/schemas/data-view-1.1.json','oneOf':[view,patch],'$defs':{'column':column,'row':row,'source':source,'chart':chart,'filter':flt,'sort':sort}}
Path('assets/visual-engine/data-schema.json').write_text(json.dumps(schema,indent=2),encoding='utf8')
